"""Current-format fixtures shared by pipeline and reporting tests."""
from pathlib import Path
import tomllib

from radar.common.csvio import atomic_write_csv
from radar.common.run import utc_now


def collect_paper_fixture(settings, profile, cache, limit=None, client=None):
    """Exercise the paper adapter with API pages generated by small iterator fixtures."""
    import math
    from radar.adapters.openalex import OpenAlexAdapter
    from radar.openalex.collect import OpenAlexClient
    from radar.common.limits import query_result_limit

    modern = {**profile, "schema_version": "1.0", "provider": "openalex", "named_entity_seeding": False,
        "search_parameter": "search", "from_publication_date": "1900-01-01", "to_publication_date": "2026-10-14"}

    class Transport:
        """Turn finite fixture iterators into actual cursor-paginated API responses."""
        select = OpenAlexClient.select

        def __init__(self):
            """Initialize the query response inventory."""
            self.queries = {}

        def get(self, path, params):
            """Return provider-native results while retaining fixture query-cap observations."""
            text, size = params["search"], params["per-page"]
            if text not in self.queries:
                factor = "survey_query_limit_factor" if text in profile.get("survey_queries", []) else "query_limit_factor"
                cap = query_result_limit(settings, limit, factor)
                pages = None if cap is None else math.ceil(cap / size)
                self.queries[text] = list(client.search(text, size, pages))
            records = self.queries[text]
            offset = 0 if params["cursor"] == "*" else int(params["cursor"])
            stop = min(offset + size, len(records))
            return {"results": records[offset:stop], "meta": {"count": len(records),
                "next_cursor": str(stop) if stop < len(records) else None}}

        def works_by_ids(self, identifiers):
            """Resolve reference fixtures without any network operation."""
            yield from client.works_by_ids(identifiers)

    adapter = OpenAlexAdapter(settings, cache.path.parent / 'search.toml', Transport())
    return adapter.collect_catalogue(settings, modern, cache, limit)

ROOT = Path(__file__).resolve().parents[1]
with (ROOT / 'config/studies/ids_repositories/taxonomy.toml').open('rb') as handle:
    SYSTEM_TYPE_PROFILE = tomllib.load(handle)


def write_csv(path, rows, columns):
    """Write classification fixtures with an explicit supported-field declaration."""
    rows = [dict(row) for row in rows]
    columns = list(columns)
    identities = {'github_repo_id', 'openalex_id', 'repo_id', 'paper_id', 'doi', 'entity_id'}
    classified = any('decision' in row and identities.intersection(row) for row in rows)
    if classified:
        for row in rows:
            row.setdefault('classifier_supported_fields', '*')
            if 'openalex_id' in row and row.get('artifact_name'):
                row['artifact_display_name'] = row.get('artifact_display_name') or row['artifact_name']
                row['resource_name'] = row['artifact_display_name']
        for field in ('artifact_display_name', 'resource_name'):
            if any(field in row for row in rows) and field not in columns:
                columns.append(field)
        if 'classifier_supported_fields' not in columns:
            columns.append('classifier_supported_fields')
    return atomic_write_csv(path, rows, columns)


def fixture_collection(cache, source):
    """Record the explicit selection used by a prefilter fixture."""
    namespace, field = ('github.repository', 'repository_ids') if source == 'github' else ('openalex.work', 'work_ids')
    selection = cache.get_record(source + '.collection', 'latest') or {field: [key for key, _, _ in cache.records(namespace)]}
    selection['selected_at'] = utc_now()
    cache.put_record(source + '.collection', 'latest', selection, selection['selected_at'])
    return cache
